/// <summary>
/// AVA
/// </summary>
void close()
{
    ProdTable           buffer;
    FormDataSource      fds;

    next Close();

    if (this.args().caller() && this.args().dataset() == tableNum(ProdTable))
    {
        buffer = this.args().record();
        fds = FormDataUtil::getFormDataSource(buffer);
        fds.research(true);
    }
}
